"""Offline own-species width evidence and native-fin cutout review; no approval."""
import argparse,html,json,os,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];sys.path[:0]=[str(HERE),str(HERE/'portable')]
from glb_io import sha
from audit_transverse_width import audit
def read(p):return json.loads(Path(p).read_text(encoding='utf8'))
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--catalog',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert out.is_relative_to(ROOT/'projects/fishing-2d/plans/reviews');out.parent.mkdir(parents=True,exist_ok=True);rows=[];inputs={str(a.catalog.resolve()):sha(a.catalog)}
 def uri(path):return Path(os.path.relpath(path,out.parent)).as_posix()
 for e in read(a.catalog)['records']:
  C=Path(e['candidate']);O=C.parent;D=C/('delivery-r2'if e['species']=='sea_bass'else'delivery');I=D/'review';old=read(O/'baseline-width.validation.json');plan=read(O/'width-r1/deformation.plan.json');current=audit(C/'source-run/final-spec.json',e['entry']['scientific_name'],Path(old['sources']['csv']));report=C/'width-final.validation.json'
  if report.exists():assert read(report)==current
  else:report.write_bytes((json.dumps(current,ensure_ascii=False,indent=2)+'\n').encode())
  images=[('宽度调整前：俯视灰模',O/'width-r1/review-r2/before-whole-top-clay.png'),('宽度调整后：俯视灰模',C/'review/after-whole-top-clay.png'),('实际冷读整鱼',I/'whole-left-texture.png'),('头嘴近景',I/'head-contact.jpg')]
  # Capture filenames are read from real existing outputs, never synthesized.
  if not images[0][1].exists():
   before=sorted((O/'width-r1/review-r2').glob('*before*top*clay*'));after=sorted((C/'review').glob('*after*top*clay*'));assert len(before)==len(after)==1,(before,after);images[:2]=[('宽度调整前：俯视灰模',before[0]),('宽度调整后：俯视灰模',after[0])]
  images +=[(f'原像素切片 / 实际贴图 / 灰模 {i+1}',C/f'fin-volume/native-source-review-{i}.jpg')for i in range(3)]
  images += [('动作视频',I/'review.mp4')]
  for _,path in images:assert path.is_file(),path;inputs[str(path)]=sha(path)
  inputs.update({str(x.resolve()):sha(x)for x in [report,O/'baseline-width.validation.json',O/'width-r1/deformation.plan.json']})
  rows.append({'species':e['species'],'scientific':e['entry']['scientific_name'],'before':old['sections'],'after':current['sections'],'specimens':old['empirical'],'limits':old['limits'],'targets':plan['target_width_stations_cm'],'model_sha256':current['model_sha256'],'triangles':read(C/'source-run/final-spec.json')['expected']['triangles'],'images':[{'label':label,'url':uri(path),'video':path.suffix=='.mp4'}for label,path in images]})
 data=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
 template='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>五鱼宽度与精细抠图对照</title><style>body{background:#17252c;color:#e9f0ef;font:16px system-ui;margin:24px auto;max-width:1380px}button{padding:12px;margin:5px;background:#304952;color:white;border:1px solid #78969d;cursor:pointer}button.active{background:#42756f}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{padding:8px;text-align:left;border-bottom:1px solid #49606a}small{color:#a4bcc4}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}img,video{width:100%;background:#25343c;image-rendering:pixelated}img{cursor:zoom-in}img.big{position:fixed;inset:2vh 2vw;width:96vw;height:96vh;object-fit:contain;background:#17252cf5;z-index:5;cursor:zoom-out}figure{margin:0}svg{width:100%;height:260px;background:#203139}a{color:#9de1d1}</style><h1>五鱼宽度与精细抠图对照</h1><p>待用户外观确认。保留原画RGB；精细化针对鳍的漏抠、余边、白边及异材质边缘。点击图片可放大。</p><nav></nav><main></main><script>const records=DATA;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function show(i){const r=records[i];document.querySelectorAll('button').forEach((b,j)=>b.classList.toggle('active',i===j));const after=new Map(r.after.map(x=>[x.s_from_nose_over_visible_TL,x]));const max=Math.max(...r.before.map(x=>x.width_cm),...r.after.map(x=>x.width_cm))*1.1;const points=arr=>arr.map(x=>`${50+x.s_from_nose_over_visible_TL*1100},${230-x.width_cm/max*200}`).join(' ');document.querySelector('main').innerHTML=`<h2>${esc(r.species)} · ${esc(r.scientific)}</h2><p>${r.triangles} 三角面；头型侧面XY、嘴唇UV/原色和正常动作保留。宽度曲线属于D级制作推断。</p><svg viewBox="0 0 1200 260"><polyline points="${points(r.before)}" fill="none" stroke="#a0a9b1" stroke-width="3"/><polyline points="${points(r.after)}" fill="none" stroke="#7de3c8" stroke-width="3"/><text x="50" y="25" fill="white">横轴：距吻端 / 展示总长；纵轴：身体横截面宽(cm)。灰：修改前，绿：修改后。</text></svg><p>证据来源：<a href="https://zenodo.org/records/6642650">FishShapes / Smithsonian保存标本，CC0</a>。同种样本小，观测范围不是种群界限；最大宽度与最大体高的测站未必相同。SL不能直接当TL，Mouth_width为颌关节跨度。</p><table><tr><th>标本</th><th>标准长 mm</th><th>最大宽 mm</th><th>最大体高 mm</th><th>W/H</th></tr>${r.specimens.map(s=>`<tr><td>${esc(s.specimen_id)}</td><td>${s.original.Standard_length}</td><td>${s.original.Max_fish_width}</td><td>${s.original.Max_body_depth}</td><td>${s.W_over_H.toFixed(3)}</td></tr>`).join('')}</table><details><summary>实际有限截面逐站数据；头宽/唇宽没有生物实测，目标为制作参数</summary><pre>${esc(JSON.stringify(r.targets,null,2))}</pre><table><tr><th>距吻端 / TL</th><th>原宽 cm</th><th>现宽 cm</th></tr>${r.before.filter(s=>after.has(s.s_from_nose_over_visible_TL)).map(s=>`<tr><td>${s.s_from_nose_over_visible_TL}</td><td>${s.width_cm.toFixed(3)}</td><td>${after.get(s.s_from_nose_over_visible_TL).width_cm.toFixed(3)}</td></tr>`).join('')}</table></details><div class="grid">${r.images.map(im=>`<figure><figcaption>${esc(im.label)}</figcaption>${im.video?`<video controls preload="metadata" src="${esc(im.url)}"></video>`:`<img loading="lazy" src="${esc(im.url)}" onclick="this.classList.toggle('big')">`}</figure>`).join('')}</div><p><small>冷读模型 SHA256 ${r.model_sha256}。离散490姿态通过也不证明全连续时间；本页不代表用户验收。</small></p>`}document.querySelector('nav').innerHTML=records.map((r,i)=>`<button onclick="show(${i})">${esc(r.species)}</button>`).join('');show(0)</script></html>'''
 out.write_text(template.replace('DATA',data),encoding='utf8');receipt={'ok':True,'kind':'offline_width_and_native_cutout_evidence','catalog_sha256':sha(a.catalog),'inputs':inputs,'html':str(out),'html_sha256':sha(out),'user_acceptance':False};out.with_suffix('.validation.json').write_bytes((json.dumps(receipt,ensure_ascii=False,indent=2)+'\n').encode());print(json.dumps({'ok':True,'html':str(out)}))
if __name__=='__main__':main()
